create extension if not exists postgis;
create table if not exists freebies(id uuid primary key default gen_random_uuid(),title text not null,description text,category text not null,venue text,location geography(point,4326) not null,starts_at timestamptz,ends_at timestamptz,expires_at timestamptz,free_type text not null default 'free' check(free_type in ('free','signup')),requirements text,source_name text,source_url text,source_id text,verification_status text not null default 'unverified',confidence numeric default .5,last_verified_at timestamptz,created_at timestamptz default now(),unique(source_name,source_id));
create index if not exists freebies_location_idx on freebies using gist(location);
create table if not exists submissions(id uuid primary key default gen_random_uuid(),title text not null,venue text not null,category text,source_url text,status text default 'pending',created_at timestamptz default now());
create or replace function nearby_freebies(user_lat double precision,user_lng double precision,radius_miles double precision default 25) returns table(id uuid,title text,category text,venue text,distance_miles double precision,starts_at timestamptz,free_type text,source_url text) language sql stable as $$ select f.id,f.title,f.category,f.venue,ST_Distance(f.location,ST_SetSRID(ST_MakePoint(user_lng,user_lat),4326)::geography)/1609.344,f.starts_at,f.free_type,f.source_url from freebies f where ST_DWithin(f.location,ST_SetSRID(ST_MakePoint(user_lng,user_lat),4326)::geography,radius_miles*1609.344) and (f.expires_at is null or f.expires_at>now()) order by f.location <-> ST_SetSRID(ST_MakePoint(user_lng,user_lat),4326)::geography limit 100; $$;